result = {"Sub_total": []}

for line in record.invoice_line_ids:
  if line.product_id.default_code == 'DETIMP':
    house_id = line.nvocc_service_job_id.id or ''
    total_currency_amount = line.charge_rate_per_unit * line.quantity
    subtotal = total_currency_amount 
    vat = (line.price_total - line.price_subtotal) 
    discount = line.discount and (line.quantity * line.charge_rate_per_unit * line.discount)/100 or 0
    found = False
    for sub_total in result["Sub_total"]:
        if sub_total["Id"] == house_id:
            sub_total["Value"]["invoice_line_ids"].append({
                "line_id": line.id
            })
            sub_total["Value"]["subtotal"] += subtotal
            sub_total["Value"]["total"] += vat + subtotal - discount
            found = True
            break

    if not found:
        result["Sub_total"].append({
            "Id": house_id,
            "Value": {
                "invoice_line_ids": [{
                    "line_id": line.id

                }],
                "subtotal": subtotal,
                "total": vat + subtotal -discount 
            }
        })

final_total = 0
sub_total_all_houses = 0 

for house_total in result["Sub_total"]:
    final_total += house_total["Value"]["total"]
    sub_total_all_houses += house_total["Value"]["subtotal"]
    house_total["Value"]["subtotal"] = "{:,.2f}".format(house_total["Value"]["subtotal"])
    house_total["Value"]["total"] = "{:,.2f}".format(house_total["Value"]["total"])

result["final_total_for_all_houses"] = "{:,.2f}".format(final_total)
result["subtotal_for_all_houses"] = "{:,.2f}".format(sub_total_all_houses)

